import csv

def verify_stops():
    stops_ids = set()
    with open('outputs/t05_clean_stops.csv', 'r', encoding='utf-8') as f:
        reader = csv.DictReader(f)
        for row in reader:
            try:
                stops_ids.add(int(row['stop_id']))
            except ValueError:
                stops_ids.add(row['stop_id'])

    missing_ids = []
    with open('outputs/t09_poi_nearest_stop.csv', 'r', encoding='utf-8') as f:
        reader = csv.DictReader(f)
        for row in reader:
            sid = row['nearest_stop_id']
            try:
                sid = int(sid)
            except ValueError:
                pass
            if str(sid) not in [str(s) for s in stops_ids]:
                missing_ids.append((row['qid'], sid))

    if missing_ids:
        print(f"Missing stop IDs: {missing_ids}")
        return False
